"use client";
import type { ComponentProps, CSSProperties } from "react";
import { cn } from "./lib/cn";
import "./battery-meter.css";

export type BatteryMeterProps = Omit<ComponentProps<"div">, "children"> & {
  /** Charge from 0 to 100. */
  level: number;
  charging?: boolean;
  /** Writes the percentage beside the cell. */
  showValue?: boolean;
  /** What the battery belongs to, e.g. "Sensor battery". */
  label?: string;
};

/**
 * A battery cell that fills and drains with the level. It stays in the foreground colour until 20%, turns amber
 * at 20% and red at 10%, and while charging a soft light sweeps across the fill and a bolt appears. The level is
 * exposed as a meter with the percentage and charging state in its value text. Under reduced motion the sweep
 * stops and the fill changes without easing.
 */
export function BatteryMeter({ level, charging, showValue = true, label = "Battery", className, style, ...props }: BatteryMeterProps) {
  const value = Math.max(0, Math.min(100, Math.round(level)));
  const tone = value <= 10 ? "critical" : value <= 20 ? "low" : "ok";
  return (
    <div
      role="meter"
      aria-label={label}
      aria-valuemin={0}
      aria-valuemax={100}
      aria-valuenow={value}
      aria-valuetext={`${value}%${charging ? ", charging" : ""}`}
      data-slot="battery-meter"
      data-tone={tone}
      data-charging={charging ? "" : undefined}
      className={cn("inline-flex items-center gap-2", className)}
      style={{ "--bat-level": value / 100, ...style } as CSSProperties}
      {...props}
    >
      <span data-slot="bat-body" aria-hidden="true">
        <span data-slot="bat-cell">
          <span data-slot="bat-fill" />
        </span>
      </span>
      {charging ? (
        <svg data-slot="bat-bolt" viewBox="0 0 24 24" aria-hidden="true">
          <path d="M13 2 5 13.5h5.5L9.5 22 19 9.5h-6z" />
        </svg>
      ) : null}
      {showValue ? (
        <span data-slot="bat-value" aria-hidden="true">
          {value}%
        </span>
      ) : null}
    </div>
  );
}

import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/* battery-meter.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  /* Battery meter: the fill slides in from the left inside a clipped cell; charging adds a sweep of light. */
  [data-slot="battery-meter"] { --bat-color: var(--foreground); color: var(--foreground); font-size: 13px; font-variant-numeric: tabular-nums; }
  [data-slot="battery-meter"][data-tone="low"] { --bat-color: var(--warning); }
  [data-slot="battery-meter"][data-tone="critical"] { --bat-color: var(--destructive); }
  [data-slot="battery-meter"][data-charging] { --bat-color: var(--success); }
  [data-slot="battery-meter"] [data-slot="bat-body"] { position: relative; width: 36px; height: 18px; flex: none; border: 1.5px solid var(--border-strong); border-radius: 8px; }
  [data-slot="battery-meter"] [data-slot="bat-body"]::after { content: ""; position: absolute; right: -5px; top: 50%; width: 3px; height: 7px; margin-top: -3.5px; border-radius: 0 3px 3px 0; background: var(--border-strong); }
  [data-slot="battery-meter"] [data-slot="bat-cell"] { position: absolute; inset: 2px; overflow: hidden; border-radius: 4px; }
  [data-slot="battery-meter"] [data-slot="bat-fill"] { position: absolute; inset: 0; border-radius: 4px; background: var(--bat-color); translate: calc((var(--bat-level) - 1) * 100%) 0; transition: translate var(--duration-deliberate) var(--ease-out), background-color var(--duration-normal) var(--ease-out); }
  [data-slot="battery-meter"][data-charging] [data-slot="bat-fill"]::after { content: ""; position: absolute; inset: 0; background: linear-gradient(100deg, transparent 30%, color-mix(in oklab, var(--background) 55%, transparent) 50%, transparent 70%); animation: bat-sweep 1.8s var(--ease-in-out) infinite; }
  [data-slot="battery-meter"] [data-slot="bat-bolt"] { width: 14px; height: 14px; flex: none; fill: var(--success); animation: bat-bolt var(--duration-normal) var(--ease-settle); }
  [data-slot="battery-meter"] [data-slot="bat-value"] { min-width: 3.4ch; color: var(--muted-foreground); }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="battery-meter"] [data-slot="bat-fill"] { transition: none; }
    [data-slot="battery-meter"] [data-slot="bat-fill"]::after, [data-slot="battery-meter"] [data-slot="bat-bolt"] { animation: none; }
  }
  @keyframes bat-sweep { from { translate: -100% 0; } to { translate: 100% 0; } }
  @keyframes bat-bolt { from { scale: 0.4; opacity: 0; } to { scale: 1; opacity: 1; } }
}
